// 机器人型号

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'

export const useVersionStore = defineStore('version', () => {
  const robotType = ref('')
  const routerEnabled = ref(false)

  // 版本映射表，需要和后端（key）保持一致（key-后端定义，value前端定义）
  const VERSION_MAP = {
    //1.0
    'tiangong-lite': 'tg-l',
    'tianyi-lite': 'ty-l',
    'tianyi-proD': 'ty-pd',
    //2.0
    'TG2.0-Lite': 'tg-l-2',
    'TG2.0-Pro': 'tg-p-2',
    'TG2.0-Plus': 'tg-u-2',
    'TY2.0-ProD': 'ty-pd-2',
    // 工站（天书）系列
    'TS1.0LITE-H': 'gz-l-h',
    'TS1.0PLUS-H': 'gz-p-h',
    'TS1.0LITE': 'gz-l',
    'TS1.0PLUS': 'gz-p',
    // 天工2.0Pro/Plus雷达版 （新增的，不走原来路由逻辑，所以这里value单独处理了）
    'TG2.0-Pro-lidar': 'TG2.0-Pro-lidar',
    'TG2.0-Plus-lidar': 'TG2.0-Plus-lidar',
  }

  const currentVersion = computed(() => {
    return VERSION_MAP[robotType.value] || ''
  })

  const setRobotType = (type) => {
    robotType.value = type
  }

  const setRouterEnabled = (status) => {
    routerEnabled.value = status
  }

  return {
    currentVersion,
    robotType: computed(() => robotType.value), // 提供机器人型号只读访问
    routerEnabled,
    setRobotType,
    setRouterEnabled
  }
})
