// 品牌设定（目前只有 ubtech 和默认人创）

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'

/**
 * brandState: 'unknown' | 'default' | 'ubtech'
 * unknown：还没拿到第一帧，不渲染图
 * default：没有 robotLogo 字段或不是 'ubtech'，渲染默认
 * ubtech：robotLogo === 'ubtech'，渲染 ubtech 资源
 */

export const useBrandStore = defineStore('brand', () => {
  const brandState = ref('unknown')

  const brandReady = computed(() => brandState.value !== 'unknown')
  const isUbtech = computed(() => brandState.value === 'ubtech')

  function setByRobotLogo(robotLogo) {
    if (robotLogo === 'ubtech') {
      brandState.value = 'ubtech'
    } else {
      // 包含：字段缺失 / 为空 / 其它值
      brandState.value = 'default'
    }
  }

  return { brandState, brandReady, isUbtech, setByRobotLogo }
})
